<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>body{font-family:Arial;background:#f5f7fb;margin:0;color:#1f2937}.wrap{max-width:1200px;margin:auto;padding:25px}.card{background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:18px;margin-top:18px}input,select{padding:8px;border:1px solid #d0d5dd;border-radius:7px}button,.btn{padding:8px 11px;border:0;border-radius:7px;background:#2563eb;color:#fff;text-decoration:none}table{width:100%;border-collapse:collapse;margin-top:15px}th,td{padding:9px;border-bottom:1px solid #eee;text-align:left}</style></head><body><div class="wrap"><a href="{{route('admin.dashboard')}}">Dashboard</a> | <a href="{{route('admin.userfinance.passbook')}}">User Passbook</a> | <a href="{{route('admin.userfinance.payments')}}">User Payments</a> | <a href="{{route('admin.userfinance.withdrawals')}}">User Withdrawals</a><h1>User Payments</h1><div class="card"><form><input name="user_no" placeholder="User No" value="{{request('user_no')}}"><input name="transaction_id" placeholder="Transaction ID" value="{{request('transaction_id')}}"><button>Filter</button></form><table><tr><th>Date</th><th>User</th><th>No</th><th>Amount</th><th>Points</th><th>Rate</th><th>Transaction</th><th>Medium</th></tr>@foreach($items as $x)<tr><td>{{$x->payment_date}}</td><td>{{$x->firstname}} {{$x->lastname}}</td><td>{{$x->user_no}}</td><td>{{$x->amount}}</td><td>{{$x->withdrawal_point}}</td><td>{{$x->conversion_rate}}</td><td>{{$x->transaction_id}}</td><td>{{$x->payment_medium_id}}</td></tr>@endforeach</table>{{$items->links()}}</div></div></body></html>